//===========================================
//Bit define
//===========================================

//BN_ACCMODE
#if 0
#define ACCMODE_DISABLE                     (0)
#define ACCMODE_MLTBNK                      (BIT0)
#define ACCMODE_MLTBNKO12                   (BIT1)
#define ACCMODE_MLTBNKO34                   (BIT2)
#define ACCMODE_MLTBNKIM                    (BIT5)
#define ACCMODE_BURST_MODE_FIXED_ADDRESS    (BIT6)  //For BN_ACCMODE register, 1 Serial burst mode: fixed address
#define ACCMODE_BURST_MODE_AUTO_INC_ADDRESS (BIT7)  //For BN_ACCMODE register, 2 Serial burst mode: address automatic increment
#endif

typedef enum
{
    eRA_NORMAL                      = 0,
    eRA_MLTBNK                      = (0x01 << 0), //= BIT0,  //Register access between multiple banks (CH14)
    eRA_MLTBNKO12                   = (0x01 << 1), //= BIT1,  //Register access between multiple banks (outputs of CH1 and 2)
    eRA_MLTBNKO34                   = (0x01 << 2), //= BIT2,  //Register access between multiple banks (outputs of CH3 and 4)
    eRA_MLTBNKIM                    = (0x01 << 5), //= BIT5,  //Register access between multiple banks (inputs of CH14 and the memory setting area)
    eRA_BURST_MODE_FIXED_ADDRESS    = (0x01 << 6), //= BIT6,  //BST[1:0]: 4-wire serial/parallel access burst mode select  // b7b6=> 00:Normal mode, 01:burst mode: address fixed, 10:Serial/parallel burst mode: address auto increment, 11:TBD
    eRA_BURST_MODE_AUTO_INC_ADDRESS = (0x01 << 7), //= BIT7,  //BST[1:0]: 4-wire serial/parallel access burst mode select

    eRA_INVALID,
}eREG_ACCMODE;


//B4_CPUWAD
#define CPUWAD_WRBMPFMT (BIT31)  //0: Disable
                                 //1: Enable. Data can be written into DDR3-SDRAM in the order of B, G and R

#define CPUWAD_MASK 0x7FFFFFFF

//B9_OSDMODE
#define CPLTEN (BIT14)
#define OSDH2X (BIT12)
#define OSDV2X (BIT11)


